
@use './面板样式.scss';

.zx-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(165px, 1fr));
  gap: 8px;
}

.zx-cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 9px 11px;
  border: 1px solid var(--zx-线);
  border-radius: 3px;
  background: var(--zx-纸);
}

.zx-cell-k {
  font-size: 10.5px;
  color: var(--zx-墨淡);
  letter-spacing: 0.05em;
}

.zx-cell-v {
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.zx-sec {
  margin-top: 14px;
}

.zx-sec-head {
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--zx-线);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.zx-sec-sub {
  font-size: 10.5px;
  font-weight: 400;
  color: var(--zx-墨淡);
}

.zx-line {
  margin: 8px 0 0;
  font-size: 11.5px;
  line-height: 1.65;
}

.zx-dim {
  color: var(--zx-墨淡);
}

.zx-note {
  margin: 8px 0 0;
  padding: 8px 11px;
  border-left: 2px solid var(--zx-主淡);
  background: var(--zx-纸深);
  font-size: 12px;
  line-height: 1.6;
}
