
@use './面板样式.scss';

.zx-sec {
  margin-bottom: 16px;
}

.zx-sec-head {
  padding-bottom: 6px;
  border-bottom: 1px solid var(--zx-线);
  font-size: 12.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
}

.zx-line {
  margin: 8px 0 0;
  font-size: 11.5px;
  line-height: 1.65;
}

.zx-dim {
  color: var(--zx-墨淡);
}

.zx-list {
  margin-top: 8px;
}

.zx-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: baseline;
  gap: 10px;
  padding: 6px 0;
  border-bottom: 1px dashed var(--zx-线);
  font-size: 12px;
}

.zx-row-name {
  color: var(--zx-墨);
}

.zx-row-tag {
  font-size: 11px;
  color: var(--zx-墨淡);
}

.zx-row-num {
  font-size: 11.5px;
  color: var(--zx-主);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 560px) {
  .zx-row {
    grid-template-columns: minmax(0, 1fr) auto;
  }
  .zx-row-tag {
    grid-column: 1 / -1;
  }
}
